1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/url"
10		"sort"
11		"strings"
12	)
13	
14	// Route is one configured route: an id, accepted methods, a path prefix and
15	// the upstream URL requests on that route are forwarded to. An optional
16	// queryTransforms list rewrites the request query string after the route has
17	// been selected.
18	type Route struct {
19		ID              string            `json:"id"`
20		Methods         []string          `json:"methods"`
21		PathPrefix      string            `json:"pathPrefix"`
22		Upstream        string            `json:"upstream"`
23		QueryTransforms []*QueryTransform `json:"-"`
24	
25		// queryTransformsRaw holds the undecoded queryTransforms value until
26		// Config.UnmarshalJSON validates it once the route's position in its own
27		// config is known.
28		queryTransformsRaw json.RawMessage
29	}
30	
31	// QueryTransform is one rule in a route's queryTransforms array: op is
32	// "set", "remove" or "rename"; name is matched against decoded parameter
33	// names, value (set only) is used literally, and to (rename only) is the
34	// literal replacement name.
35	type QueryTransform struct {
36		Op    string `json:"op"`
37		Name  string `json:"name"`
38		Value string `json:"value"`
39		To    string `json:"to"`
40	}
41	
42	// routeJSON mirrors Route but keeps every field raw: the basic fields are
43	// type-checked in Config.UnmarshalJSON with the route's position (and, when
44	// available, its id), so a wrong field type is reported on that route rather
45	// than as a generic JSON decode error, and queryTransforms can surface
46	// null, wrong types and malformed rules the same way.
47	type routeJSON struct {
48		ID              json.RawMessage `json:"id"`
49		Methods         json.RawMessage `json:"methods"`
50		PathPrefix      json.RawMessage `json:"pathPrefix"`
51		Upstream        json.RawMessage `json:"upstream"`
52		QueryTransforms json.RawMessage `json:"queryTransforms"`
53	}
54	
55	// decodeRoute type-checks and decodes one raw route object. loc is the
56	// route's 1-based location in its config (e.g. "route 2"). Field type errors
57	// carry that location and, when the route supplies a valid non-empty string
58	// id anywhere in its object (even after the offending field), that id.
59	// Missing fields stay silent here and are rejected later by validate, which
60	// preserves the existing missing-field behavior.
61	func decodeRoute(data []byte, loc string) (Route, *Failure) {
62		var rj routeJSON
63		if err := json.Unmarshal(data, &rj); err != nil {
64			// A type error at this level means the route itself is not a JSON
65			// object (e.g. an entry of routes that is a string or number).
66			return Route{}, failuref("invalid_config", "%s: route entry must be a JSON object", loc)
67		}
68	
69		var route Route
70		// Type-check id first so it can identify the route on an error in any
71		// later field regardless of object order. Only a valid non-empty JSON
72		// string becomes the label; a wrong-typed id is reported against the id
73		// field and never rendered (e.g. as a number or object) as the route's
74		// identity.
75		if f := decodeStringField(rj.ID, loc, "id", &route.ID); f != nil {
76			return Route{}, f
77		}
78		label := loc
79		if route.ID != "" {
80			label = routeLabel(loc, route.ID)
81		}
82	
83		if f := decodeMethodsField(rj.Methods, label, &route.Methods); f != nil {
84			return Route{}, f
85		}
86		if f := decodeStringField(rj.PathPrefix, label, "pathPrefix", &route.PathPrefix); f != nil {
87			return Route{}, f
88		}
89		if f := decodeStringField(rj.Upstream, label, "upstream", &route.Upstream); f != nil {
90			return Route{}, f
91		}
92		route.queryTransformsRaw = rj.QueryTransforms
93		return route, nil
94	}
95	
96	// decodeStringField type-checks a raw route field that must hold a string.
97	// An absent field is left as the zero value for later required-field
98	// validation; null or any non-string JSON value fails here.
99	func decodeStringField(raw json.RawMessage, label, field string, dst *string) *Failure {
100		if len(raw) == 0 {
101			return nil
102		}
103		if !jsonString(raw, dst) {
104			return failuref("invalid_config", "%s: %s must be a string", label, field)
105		}
106		return nil
107	}
108	
109	// decodeMethodsField type-checks methods: it must be an array of strings
110	// when present. An absent field is left nil for later required-field
111	// validation; null or any non-array value fails the field, and a number,
112	// boolean, object or null entry fails with the offending entry's position.
113	func decodeMethodsField(raw json.RawMessage, label string, dst *[]string) *Failure {
114		if len(raw) == 0 {
115			return nil
116		}
117		body := bytes.TrimSpace(raw)
118		if string(body) == "null" || len(body) == 0 || body[0] != '[' {
119			return failuref("invalid_config", "%s: methods must be an array of strings", label)
120		}
121		var elems []json.RawMessage
122		if err := json.Unmarshal(body, &elems); err != nil {
123			return failuref("invalid_config", "%s: methods must be an array of strings", label)
124		}
125		methods := make([]string, 0, len(elems))
126		for i, elem := range elems {
127			var m string
128			if !jsonString(bytes.TrimSpace(elem), &m) {
129				return failuref("invalid_config", "%s: methods entry %d must be a string", label, i+1)
130			}
131			methods = append(methods, m)
132		}
133		*dst = methods
134		return nil
135	}
136	
137	// parseQueryTransforms decodes and validates the raw queryTransforms array
138	// of one route. loc identifies the route; rule errors additionally carry a
139	// 1-based rule index.
140	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
141		body := strings.TrimSpace(string(raw))
142		if body == "null" {
143			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
144		}
145		var elems []json.RawMessage
146		if err := json.Unmarshal([]byte(body), &elems); err != nil {
147			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
148		}
149		transforms := make([]*QueryTransform, 0, len(elems))
150		for i, elem := range elems {
151			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
152			if string(bytes.TrimSpace(elem)) == "null" {
153				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
154			}
155			var fields map[string]json.RawMessage
156			if err := json.Unmarshal(elem, &fields); err != nil {
157				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
158			}
159	
160			qt := &QueryTransform{}
161			opRaw, ok := fields["op"]
162			switch {
163			case !ok:
164				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
165			case !jsonString(opRaw, &qt.Op):
166				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
167			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
168				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
169			}
170	
171			nameRaw, ok := fields["name"]
172			switch {
173			case !ok:
174				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
175			case !jsonString(nameRaw, &qt.Name):
176				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
177			case qt.Name == "":
178				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
179			}
180	
181			valueRaw, hasValue := fields["value"]
182			toRaw, hasTo := fields["to"]
183			switch qt.Op {
184			case "set":
185				if !hasValue {
186					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
187				}
188				if !jsonString(valueRaw, &qt.Value) {
189					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
190				}
191			case "remove":
192				if hasValue {
193					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
194				}
195			case "rename":
196				if hasValue {
197					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
198				}
199				switch {
200				case !hasTo:
201					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
202				case !jsonString(toRaw, &qt.To):
203					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
204				case qt.To == "":
205					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
206				}
207			}
208			transforms = append(transforms, qt)
209		}
210		return transforms, nil
211	}
212	
213	// jsonString decodes raw into s and reports whether raw is a JSON string
214	// (null, numbers, objects and arrays fail).
215	func jsonString(raw json.RawMessage, s *string) bool {
216		if len(raw) == 0 || raw[0] != '"' {
217			return false
218		}
219		return json.Unmarshal(raw, s) == nil
220	}
221	
222	// routeLabel renders the human-readable route location, adding the id when
223	// the configuration supplied one.
224	func routeLabel(loc, id string) string {
225		if id != "" {
226			return fmt.Sprintf("%s (id %q)", loc, id)
227		}
228		return loc
229	}
230	
231	// Config is the resolve configuration: a flat array of routes.
232	type Config struct {
233		Routes []Route `json:"routes"`
234	}
235	
236	// UnmarshalJSON decodes the routes array one entry at a time and validates
237	// each entry's field types and queryTransforms against its 1-based position
238	// in this config. Decoding entries from raw values means wrong field types
239	// are reported on the offending route (with its id when available) instead
240	// of as a generic JSON syntax failure. The position comes from the array
241	// decoded here, so configs parsed concurrently or interleaved in the same
242	// process cannot shift each other's route numbering. A broken JSON document
243	// still fails the outer decode and is reported as a parse failure, without a
244	// guessed route position.
245	func (cfg *Config) UnmarshalJSON(data []byte) error {
246		var raw struct {
247			Routes []json.RawMessage `json:"routes"`
248		}
249		if err := json.Unmarshal(data, &raw); err != nil {
250			return err
251		}
252		// Pass 1: decode and type-check every entry, so a wrong field type on a
253		// later route fails before any queryTransforms validation (matching the
254		// precedence of decoding before validation).
255		cfg.Routes = make([]Route, len(raw.Routes))
256		for i, entry := range raw.Routes {
257			route, f := decodeRoute(entry, fmt.Sprintf("route %d", i+1))
258			if f != nil {
259				return f
260			}
261			cfg.Routes[i] = route
262		}
263		// Pass 2: validate each route's queryTransforms now that every position
264		// is known.
265		for i := range cfg.Routes {
266			route := &cfg.Routes[i]
267			if len(route.queryTransformsRaw) == 0 {
268				continue // field absent
269			}
270			loc := fmt.Sprintf("route %d", i+1)
271			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
272			if f != nil {
273				return f
274			}
275			route.QueryTransforms = transforms
276			route.queryTransformsRaw = nil
277		}
278		return nil
279	}
280	
281	// Request is one resolution request: an HTTP method and a request target
282	// (path with an optional raw query string).
283	type Request struct {
284		Method string `json:"method"`
285		Target string `json:"target"`
286	}
287	
288	// Resolution is the successful result of matching a request.
289	type Resolution struct {
290		RouteID     string `json:"routeId"`
291		UpstreamURL string `json:"upstreamURL"`
292	}
293	
294	// Failure carries a stable machine-readable code and a human-readable reason.
295	type Failure struct {
296		Code       string   `json:"code"`
297		Reason     string   `json:"reason"`
298		Candidates []string `json:"candidates,omitempty"`
299	}
300	
301	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
302	
303	func failuref(code, format string, args ...any) *Failure {
304		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
305	}
306	
307	// ParseConfig parses and fully validates the route configuration.
308	func ParseConfig(data []byte) (*Config, *Failure) {
309		var cfg Config
310		if err := json.Unmarshal(data, &cfg); err != nil {
311			if f, ok := err.(*Failure); ok {
312				return nil, f
313			}
314			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
315		}
316		if f := cfg.validate(); f != nil {
317			return nil, f
318		}
319		return &cfg, nil
320	}
321	
322	func (cfg *Config) validate() *Failure {
323		seenIDs := make(map[string]int, len(cfg.Routes))
324		for i := range cfg.Routes {
325			route := &cfg.Routes[i]
326			loc := fmt.Sprintf("route %d", i+1)
327			if route.ID == "" {
328				return failuref("invalid_config", "%s: id must be non-empty", loc)
329			}
330			if first, ok := seenIDs[route.ID]; ok {
331				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
332			}
333			seenIDs[route.ID] = i + 1
334	
335			if len(route.Methods) == 0 {
336				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
337			}
338			for _, method := range route.Methods {
339				switch {
340				case method == "":
341					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
342				case method == "*":
343					// Wildcard matching any legal method.
344				case !isToken(method):
345					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
346				}
347			}
348	
349			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
350				return f
351			}
352			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
353				return f
354			}
355		}
356		return nil
357	}
358	
359	func validatePrefix(prefix, loc, id string) *Failure {
360		switch {
361		case prefix == "" || prefix[0] != '/':
362			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
363		case prefix != "/" && strings.HasSuffix(prefix, "/"):
364			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
365		case strings.ContainsAny(prefix, "?#"):
366			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
367		case !validPercentEscapes(prefix):
368			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
369		}
370		return nil
371	}
372	
373	func validateUpstream(raw, loc, id string) *Failure {
374		if strings.ContainsAny(raw, "?#") {
375			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
376		}
377		u, err := url.Parse(raw)
378		if err != nil {
379			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
380		}
381		if u.Scheme != "http" && u.Scheme != "https" {
382			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
383		}
384		if u.Host == "" {
385			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
386		}
387		return nil
388	}
389	
390	// requestJSON mirrors Request but keeps method and target raw, so a valid
391	// JSON document whose fields merely have the wrong JSON type is reported on
392	// the offending field instead of as a generic JSON decode error.
393	type requestJSON struct {
394		Method json.RawMessage `json:"method"`
395		Target json.RawMessage `json:"target"`
396	}
397	
398	// ParseRequest parses and validates one JSON request. Three failure shapes are
399	// kept apart: a document whose JSON syntax is broken fails as a parse failure
400	// without guessing a field; a syntactically valid non-object document (array,
401	// number, string, boolean or null) must be a JSON object; a valid object whose
402	// method or target is not a string fails on that field, naming the JSON type
403	// actually received (null counts as a type error, never as a missing field).
404	// method is always checked before target, regardless of the key order in the
405	// object. Only after both fields are present strings are their contents
406	// (required method, legal token, absolute target without a fragment or a bad
407	// percent escape) validated, so an empty string stays a content error.
408	func ParseRequest(data []byte) (*Request, *Failure) {
409		var doc json.RawMessage
410		if err := json.Unmarshal(data, &doc); err != nil {
411			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
412		}
413		body := bytes.TrimSpace(doc)
414		if len(body) == 0 || body[0] != '{' {
415			return nil, failuref("invalid_request", "request must be a JSON object")
416		}
417	
418		var rj requestJSON
419		if err := json.Unmarshal(body, &rj); err != nil {
420			// The document already parsed as one JSON value and starts with '{';
421			// keep this as a parse failure rather than a field error if the object
422			// itself cannot be read.
423			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
424		}
425	
426		var req Request
427		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
428			return nil, f
429		}
430		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
431			return nil, f
432		}
433	
434		switch {
435		case req.Method == "":
436			return nil, failuref("invalid_request", "method is required")
437		case !isToken(req.Method):
438			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
439		}
440		switch {
441		case req.Target == "" || req.Target[0] != '/':
442			return nil, failuref("invalid_request", "target must start with /")
443		case strings.Contains(req.Target, "#"):
444			return nil, failuref("invalid_request", "target must not contain a fragment")
445		case !validPercentEscapes(req.Target):
446			return nil, failuref("invalid_request", "target contains an invalid percent escape")
447		}
448		return &req, nil
449	}
450	
451	// decodeRequestStringField type-checks one request field that must hold a
452	// string. An absent field (no such key) is left as the zero value so the
453	// later content checks keep their "field is required" behavior; null or any
454	// non-string JSON value is a type error that names the field and the JSON
455	// type that was actually supplied.
456	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
457		if len(raw) == 0 {
458			return nil
459		}
460		if jsonString(raw, dst) {
461			return nil
462		}
463		return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
464	}
465	
466	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
467	// terms the request error reasons use: "null", "a boolean", "a number",
468	// "a string", "an array" or "an object".
469	func jsonTypeName(raw json.RawMessage) string {
470		switch bytes.TrimSpace(raw)[0] {
471		case 'n':
472			return "null"
473		case 't', 'f':
474			return "a boolean"
475		case '"':
476			return "a string"
477		case '[':
478			return "an array"
479		case '{':
480			return "an object"
481		default:
482			return "a number"
483		}
484	}
485	
486	// Resolve matches a validated request against a validated configuration and
487	// computes the upstream URL. Failure codes are route_not_found and
488	// route_conflict.
489	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
490		path := req.Target
491		if i := strings.IndexByte(path, '?'); i >= 0 {
492			path = path[:i]
493		}
494	
495		type candidate struct {
496			route    *Route
497			concrete bool
498		}
499		var matched []candidate
500		for i := range cfg.Routes {
501			route := &cfg.Routes[i]
502			concrete, wildcard := methodMatch(route.Methods, req.Method)
503			if !concrete && !wildcard {
504				continue
505			}
506			if !prefixMatch(route.PathPrefix, path) {
507				continue
508			}
509			matched = append(matched, candidate{route, concrete})
510		}
511		if len(matched) == 0 {
512			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
513		}
514	
515		// Longest prefix wins.
516		bestLen := 0
517		for _, c := range matched {
518			if n := len(c.route.PathPrefix); n > bestLen {
519				bestLen = n
520			}
521		}
522		winners := matched[:0]
523		for _, c := range matched {
524			if len(c.route.PathPrefix) == bestLen {
525				winners = append(winners, c)
526			}
527		}
528	
529		// Among equal prefixes a concrete method beats the wildcard.
530		var concrete []candidate
531		for _, c := range winners {
532			if c.concrete {
533				concrete = append(concrete, c)
534			}
535		}
536		if len(concrete) > 0 {
537			winners = concrete
538		}
539		if len(winners) > 1 {
540			ids := make([]string, 0, len(winners))
541			for _, c := range winners {
542				ids = append(ids, c.route.ID)
543			}
544			sort.Strings(ids)
545			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
546			f.Candidates = ids
547			return nil, f
548		}
549	
550		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
551		if f != nil {
552			return nil, f
553		}
554		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
555	}
556	
557	// methodMatch reports whether the method list matches the request method
558	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
559	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
560		for _, m := range methods {
561			switch {
562			case m == "*":
563				wildcard = true
564			case m == method:
565				concrete = true
566			}
567		}
568		return concrete, wildcard
569	}
570	
571	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
572	// treated as a separator and the root prefix matches every origin-path.
573	func prefixMatch(prefix, path string) bool {
574		if prefix == "/" {
575			return true
576		}
577		if path == prefix {
578			return true
579		}
580		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
581	}
582	
583	// joinUpstream strips the route prefix from the request path and joins the
584	// remainder onto the upstream base path with exactly one slash at the
585	// junction. The junction is one run of literal slashes: every trailing
586	// slash on the base path and every leading slash on the remainder are
587	// merged into that single slash, even when either side contributes
588	// several. Nothing else is normalized: slashes inside either part, the
589	// remainder's trailing slashes (once non-slash content has appeared),
590	// ".", ".." and percent escapes such as "%2F" are carried over byte for
591	// byte, never decoded first. The base path is sliced out of the raw
592	// upstream so joining never re-encodes, reorders or drops anything
593	// outside the junction. The raw query is preserved verbatim unless the
594	// route defines queryTransforms, in which case they rewrite it after
595	// route selection.
596	func joinUpstream(route *Route, path, target string) (string, *Failure) {
597		if _, err := url.Parse(route.Upstream); err != nil {
598			// Config validation already rejected this.
599			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
600		}
601	
602		var remainder string
603		switch {
604		case route.PathPrefix == "/":
605			// Root keeps the whole following path; "/" itself has an empty remainder.
606			if path != "/" {
607				remainder = path
608			}
609		default:
610			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
611		}
612	
613		// Slice the validated upstream raw so nothing outside the junction is
614		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
615		schemeEnd := strings.Index(route.Upstream, "://")
616		tail := route.Upstream[schemeEnd+3:]
617		hostPart, basePath := tail, ""
618		if i := strings.IndexByte(tail, '/'); i >= 0 {
619			hostPart, basePath = tail[:i], tail[i:]
620		}
621	
622		// Collapse only the junction run: all trailing slashes of the base
623		// path meet all leading slashes of the remainder, and the junction
624		// keeps exactly one slash whether or not anything follows them. A
625		// remainder made entirely of slashes has no content past the run, so
626		// it likewise ends in that single slash.
627		baseTrimmed := strings.TrimRight(basePath, "/")
628		rest := strings.TrimLeft(remainder, "/")
629		joined := baseTrimmed + "/" + rest
630	
631		result := route.Upstream[:schemeEnd+3] + hostPart + joined
632		query, f := applyQueryTransforms(route.QueryTransforms, target)
633		if f != nil {
634			return "", f
635		}
636		return result + query, nil
637	}
638	
639	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
640	func isToken(s string) bool {
641		if s == "" {
642			return false
643		}
644		for i := 0; i < len(s); i++ {
645			if !isTokenChar(s[i]) {
646				return false
647			}
648		}
649		return true
650	}
651	
652	func isTokenChar(c byte) bool {
653		switch {
654		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
655			return true
656		}
657		switch c {
658		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
659			return true
660		}
661		return false
662	}
663	
664	// validPercentEscapes checks that every "%' is followed by two hex digits.
665	// Matching and joining stay on raw strings, but malformed escapes are rejected
666	// up front for both prefixes and request targets.
667	func validPercentEscapes(s string) bool {
668		for i := 0; i < len(s); i++ {
669			if s[i] != '%' {
670				continue
671			}
672			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
673				return false
674			}
675			i += 2
676		}
677		return true
678	}
679	
680	func isHex(c byte) bool {
681		switch {
682		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
683			return true
684		}
685		return false
686	}
687

