18	func resolveJSON(t *testing.T, cfg *Config, reqSrc string) *Resolution {
19		t.Helper()
20		req, f := ParseRequest([]byte(reqSrc))
21		if f != nil {
22			t.Fatalf("unexpected request failure: %+v", f)
23		}
