130	func TestResolveJunctionSlashCollapse(t *testing.T) {
131		// Only the run where the base path's trailing slashes meet the
132		// remainder's leading slashes is collapsed to a single slash; slashes,
133		// dot segments and percent escapes anywhere else stay byte for byte.
134		cfg := mustConfig(t, `{
135		  "routes": [
136		    {"id": "multi", "methods": ["GET"], "pathPrefix": "/api",  "upstream": "http://backend.internal/base///"},
137		    {"id": "plain", "methods": ["GET"], "pathPrefix": "/v",    "upstream": "http://plain.internal/base"},
138		    {"id": "nobase","methods": ["GET"], "pathPrefix": "/n",    "upstream": "http://nb.internal:8080"},
139		    {"id": "root",  "methods": ["*"],   "pathPrefix": "/",     "upstream": "https://fallback.internal/base//"}
140		  ]
141		}`)
142	
143		cases := []struct {
144			name     string
145			request  string
146			routeID  string
147			upstream string
148		}{
149			{
150				name:     "multi-slash base and remainder collapse at the junction",
151				request:  `{"method":"GET","target":"/api//orders/7?a=1&a=&x=%2f+"}`,
152				routeID:  "multi",
153				upstream: "http://backend.internal/base/orders/7?a=1&a=&x=%2f+",
154			},
