348	func TestResolveLongestPrefixBeatsShorterConcreteMethods(t *testing.T) {
349		// Selection order: longest prefix first, concrete-vs-wildcard only among
350		// the longest-prefix winners. A concrete GET on a shorter prefix must
351		// never override a wildcard on a longer prefix, and several GET routes
352		// tied on the shorter prefix must not conflict once the longer prefix
353		// wins.
354		routes := []string{
355			`{"id":"short-one","methods":["GET"],"pathPrefix":"/a","upstream":"http://one.internal/s1"}`,
356			`{"id":"short-two","methods":["GET"],"pathPrefix":"/a","upstream":"http://two.internal/s2"}`,
357			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/base"}`,
358		}
359	
360		cases := []struct {
361			name     string
362			request  string
363			upstream string
364		}{
365			{
366				name:     "longer wildcard beats shorter concrete GETs",
367				request:  `{"method":"GET","target":"/a/b/c/items"}`,
368				upstream: "http://wild.internal/base/c/items",
369			},
370			{
371				name:     "query string survives route selection verbatim",
372				request:  `{"method":"GET","target":"/a/b/c?keep=1&keep=2&empty=&x=%2f"}`,
373				upstream: "http://wild.internal/base/c?keep=1&keep=2&empty=&x=%2f",
374			},
375			{
376				name:     "target equal to the longer prefix keeps one junction slash",
377				request:  `{"method":"GET","target":"/a/b"}`,
378				upstream: "http://wild.internal/base/",
379			},
380			{
381				name:     "wildcard on the longer prefix also serves other methods",
382				request:  `{"method":"POST","target":"/a/b/c"}`,
383				upstream: "http://wild.internal/base/c",
384			},
385		}
386		for _, order := range [][]string{routes, reversed(routes)} {
387			cfg := mustConfig(t, configFromRoutes(order...))
388			for _, tc := range cases {
389				t.Run(tc.name, func(t *testing.T) {
390					res := resolveJSON(t, cfg, tc.request)
391					if res.RouteID != "long-wild" {
392						t.Errorf("routeId = %q, want long-wild", res.RouteID)
393					}
394					if res.UpstreamURL != tc.upstream {
395						t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
396					}
397				})
398			}
399		}
400	
401		// The shorter-prefix GET routes really are tied with each other: a
402		// request that only reaches their prefix does conflict, proving the
403		// longer prefix (not an absence of rivalry) is what decided the cases
404		// above.
405		cfg := mustConfig(t, configFromRoutes(routes...))
406		_, rf := Resolve(cfg, mustReq(t, "GET", "/a/c"))
407		if rf == nil || rf.Code != "route_conflict" {
408			t.Fatalf("got %+v, want route_conflict between the shorter-prefix GET routes", rf)
409		}
410		if want := []string{"short-one", "short-two"}; !equalStrings(rf.Candidates, want) {
411			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
412		}
413	}
