660				forbidden: []string{"(id "},
661			},
662			{
663				name:      "id is an object",
664				src:       `{"routes":[{"id":{"v":1},"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
665				want:      []string{"route 1", "id must be a string"},
666				forbidden: []string{"(id "},
667			},
668			{
669				name: "pathPrefix is a number, id written after it",
670				src:  `{"routes":[{"methods":["GET"],"pathPrefix":1,"id":"orders","upstream":"http://o"}]}`,
671				want: []string{"route 1", `"orders"`, "pathPrefix must be a string"},
672			},
673			{
674				name: "upstream is a boolean, id written after it",
675				src:  `{"routes":[{"methods":["GET"],"pathPrefix":"/a","upstream":true,"id":"orders"}]}`,
676				want: []string{"route 1", `"orders"`, "upstream must be a string"},
677			},
678			{
679				name: "routes entry is not an object",
680				src:  `{"routes":[42]}`,
681				want: []string{"route 1", "route entry must be a JSON object"},
682			},
683		}
684		for _, tc := range cases {
685			t.Run(tc.name, func(t *testing.T) {
686				_, f := ParseConfig([]byte(tc.src))
687				if f == nil {
688					t.Fatalf("expected invalid_config")
689				}
690				if f.Code != "invalid_config" {
691					t.Fatalf("code = %q, want invalid_config", f.Code)
692				}
693				if strings.Contains(f.Reason, "not valid JSON") {
694					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
695				}
696				for _, want := range tc.want {
697					if !strings.Contains(f.Reason, want) {
698						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
699					}
700				}
701				for _, bad := range tc.forbidden {
702					if strings.Contains(f.Reason, bad) {
703						t.Fatalf("reason = %q must not contain %q", f.Reason, bad)
704					}
705				}
706			})
707		}
