709		// Broken JSON syntax stays a parse failure and never gets a guessed
710		// route position, even when the corruption is inside the routes array.
711		for _, src := range []string{`{not json`, `{"routes": [{"id":"x"} broken`} {
712			_, f := ParseConfig([]byte(src))
713			if f == nil || f.Code != "invalid_config" {
714				t.Fatalf("got %+v, want invalid_config for %q", f, src)
715			}
716			if !strings.Contains(f.Reason, "not valid JSON") {
717				t.Fatalf("reason = %q, want a JSON parse failure", f.Reason)
718			}
719			if strings.Contains(f.Reason, "route 1") {
720				t.Fatalf("syntax failure must not guess a route position: %q", f.Reason)
721			}
722		}
723	
724		// Fixing the second route's methods lets the request resolve normally,
725		// including through the first route it originally matched.
726		cfg := mustConfig(t, `{"routes":[
727		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
728		  {"id":"orders","methods":["GET"],"pathPrefix":"/api/orders","upstream":"http://orders.internal"}
729		]}`)
